package dev.ember.overlay.ui;

import dev.ember.overlay.api.Draw;
import dev.ember.overlay.api.Gfx;

import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

/**
 * Flat line icons for the menu (from Lucide, ISC licence - see LICENSE-lucide.txt). Each icon
 * is a 32x32 image stored as horizontal runs of four opacity levels, so it is drawn with plain
 * fills and looks the same on every Minecraft version. Generated by tools/icons.py.
 */
public final class Icons {
    private Icons() {}

    public static final int SIZE = 48;
    private static final Map<String, String> RAW = new HashMap<>();
    private static final Map<String, byte[]> DECODED = new HashMap<>();

    private static void put(String id, String b64) {
        RAW.put(id, b64);
    }

    static {
        put("fps", "");
        put("cps", "");
        put("keystrokes", "");
        put("ping", "");
        put("coords", "");
        put("direction", "");
        put("biome", "");
        put("armor", "");
        put("potions", "");
        put("stopwatch", "");
        put("clock", "");
        put("speed", "");
        put("memory", "");
        put("day", "");
        put("server", "");
        put("held", "");
        put("arrows", "");
        put("light", "");
        put("chunk", "");
        put("entities", "");
        put("session", "");
        put("target", "");
        put("food", "");
        put("radar", "");
        put("minimap", "");
        put("worldmap", "");
        put("fullbright", "");
        put("zoom", "");
        put("crosshair", "");
        put("minimal_bob", "");
        put("particles", "");
        put("hide_hand", "");
        put("cinematic_key", "");
        put("hide_scoreboard", "");
        put("hide_bossbar", "");
        put("hide_vanilla_effects", "");
        put("hide_titles", "");
        put("low_health", "");
        put("durability_warning", "");
        put("clear_water", "");
        put("item_physics", "");
        put("block_outline", "");
        put("low_fire", "");
        put("macros", "");
        put("server_switcher", "");
        put("freelook", "");
        put("snap_look", "");
        put("chat_filter", "");
        put("inventory_search", "");
        put("screenshot_manager", "");
        put("memory_cleaner", "");
        put("toggle_sprint", "");
        put("toggle_sneak", "");
        put("death_coords", "");
        put("reconnect", "");
        put("copy_coords", "");
        put("server_memory", "");
        put("ui_search", "");
        put("ui_settings", "");
        put("ui_back", "");
        put("ui_key", "");
        put("ui_layout", "");
        put("ui_all", "");
        put("ui_on", "");
        put("ui_hud", "");
        put("ui_visual", "");
        put("ui_utility", "");
        put("ui_owned", "");
        put("ui_servers", "");
        put("ui_shots", "");
        put("ui_close", "");
    }

    public static boolean has(String id) {
        return RAW.containsKey(id);
    }

    private static final Map<Long, dev.ember.overlay.api.Canvas> CANVAS = new HashMap<>();
    private static boolean canvasBroken;

    /** Draw icon {@code id} with its top-left at (x, y), {@code size} pixels wide, in {@code argb}. */
    public static void draw(Gfx g, String id, float x, float y, float size, int argb) {
        byte[] runs = DECODED.computeIfAbsent(id, k -> RAW.containsKey(k) ? Base64.getDecoder().decode(RAW.get(k)) : new byte[0]);
        if (runs.length == 0 || (argb >>> 24) == 0) return;
        // One small texture per icon and colour, painted once: a single quad per icon per frame.
        // Colours are rounded (animations pass through many) so the cache stays small.
        int qa = Math.min(255, ((argb >>> 24) + 16) / 32 * 32);
        int q = (qa << 24) | (round16((argb >> 16) & 0xFF) << 16) | (round16((argb >> 8) & 0xFF) << 8) | round16(argb & 0xFF);
        if ((q >>> 24) == 0) return;
        if (CANVAS.size() > 800) {
            CANVAS.values().forEach(v -> { if (v != null) v.close(); });
            CANVAS.clear();
        }
        final int color = q;
        dev.ember.overlay.api.Canvas c = canvasBroken ? null : CANVAS.computeIfAbsent(((long) id.hashCode() << 32) ^ (color & 0xFFFFFFFFL), k -> paint(id, runs, color));
        g.push(x, y, size / SIZE);
        if (c != null) g.canvas(c, 0, 0);
        else {
            for (int i = 0; i + 3 < runs.length; i += 4) {
                int ry = runs[i], rx = runs[i + 1], len = runs[i + 2], lvl = runs[i + 3];
                g.fill(rx, ry, rx + len, ry + 1, Draw.alpha(argb, lvl / 15f));
            }
        }
        g.pop();
    }

    private static int round16(int c) {
        return Math.min(255, (c + 8) / 16 * 16);
    }

    private static dev.ember.overlay.api.Canvas paint(String id, byte[] runs, int argb) {
        try {
            dev.ember.overlay.api.Canvas c = dev.ember.overlay.compat.Compat.canvas("icon_" + id, SIZE, SIZE);
            c.clear();
            for (int i = 0; i + 3 < runs.length; i += 4) {
                int ry = runs[i], rx = runs[i + 1], len = runs[i + 2], lvl = runs[i + 3];
                int color = Draw.alpha(argb, lvl / 15f);
                for (int xx = rx; xx < rx + len; xx++) c.set(xx, ry, color);
            }
            c.upload();
            return c;
        } catch (Throwable e) {
            System.err.println("[ember-overlay] icon textures unavailable, drawing icons with fills: " + e);
            canvasBroken = true;
            return null;
        }
    }
}
